/**
 * Reusable validation schemas and the `defineSchema` helper.
 *
 * Schema materialization requires a registered `SchemaValidator`. Veryfront
 * runtime bootstrap registers the built-in validator before handlers run.
 * `lazySchema` keeps module-scope schema constants import-safe before bootstrap.
 *
 * @example
 * ```ts
 * import { CommonSchemas, defineSchema, lazySchema } from "veryfront/schemas";
 *
 * const getUserSchema = defineSchema((v) =>
 *   v.object({
 *     id: v.string().uuid(),
 *     name: v.string().min(1),
 *   })
 * );
 * export const UserSchema = lazySchema(getUserSchema);
 *
 * export function parseEmail(input: unknown) {
 *   return CommonSchemas.email.parse(input);
 * }
 * ```
 *
 * @module schemas
 */
export { defineSchema } from "./define.js";
export { lazySchema } from "./lazy.js";
export { isOptionalSchema as schemaIsOptional, schemaToJsonSchema, } from "./json-schema.js";
export { CommonSchemas, getDateRangeSchema, getEmailSchema, getPaginationSchema, getPhoneNumberSchema, getSlugSchema, getStrongPasswordSchema, getUrlSchema, getUuidSchema, } from "./common.js";
export { getAbsolutePathSchema, getFilePathSchema, getHexColorSchema, getJsonValueSchema, getNonEmptyStringSchema, getNonNegativeIntSchema, getPortNumberSchema, getPositiveIntSchema, getSemverSchema, getTimestampSchema, } from "./primitives.js";
